  },
  "records": [
    {
      "sourceId": "california-executive-order-n-9-26",
      "title": "Executive Order N-9-26",
      "url": "https://www.gov.ca.gov/wp-content/uploads/2026/09/FINAL-N-9-26-AI-EO-9.18.26-SIGNED.pdf",
      "publisher": "State of California",
      "authority": "Signed primary legal text",
      "raw": {
        "path": "operations/product-stewards/newsstand/candidates/california-ai-oversight-order-20260920/source-refresh-20260926.json",
        "sha256": "fccd4e30c1060a89be357331229429ebd4e972fddcf1bf65593da7020dde1f95",
        "locator": "sources.0"
      },
      "exactPassages": [
        {
          "locator": "L81-L85",
          "excerpt": "No later than May 1, 2027, the Government Operations Agency shall complete the requirements of Section 8898.1 of the Government Code and develop application requirements, procedures, and criteria for independent verification organizations and publicly post them, as required by law."
        },
        {
          "locator": "L86-L89",
          "excerpt": "No later than December 1, 2027, the Government Operations Agency shall complete the requirements of subdivision (a) of Section 11549.82 of the Government Code and begin taking the actions required by subdivision (b) of that Section."
        },
        {
          "locator": "L91-L95",
          "excerpt": "The Government Operations Agency, in consultation with the Governor’s Office of Emergency Services, shall, no later than November 16, 2026, submit to my office recommendations, developed in consultation with national experts, addressing the technical feasibility and potential efficacy of amendments to existing state laws regarding AI safety and security, including at least the following:"
        },
        {
          "locator": "L96-L98",
          "excerpt": "Requiring that all large frontier developers embed designated independent verification organizations onsite in their labs to conduct periodic audits and evaluations."
        },
        {
          "locator": "L99-L102",
          "excerpt": "Requiring that the safety frameworks, transparency reports, and risk assessments that frontier AI companies are required to file be independently verified pursuant to standards determined to be adequate by an independent verification organization."
        },
        {
          "locator": "L103-L105",
          "excerpt": "Requiring the creation of a “kill switch” for frontier models, with the efficacy of the switch verified on an ongoing basis by an independent verification organization."
        },
        {
          "locator": "L106-L108",
          "excerpt": "Updating the definition of critical safety incidents that AI companies are required to report to include a range of loss-of-control incidents, covering recently reported incidents from large frontier developers."
        }
      ],
      "limitations": [
        "The order directs recommendations about possible statutory amendments; it does not itself enact the listed requirements.",
        "The order does not define a technical design for a universal shutdown mechanism."
      ]
    },
    {
      "sourceId": "governor-newsom-order-release-20260918",
      "title": "Governor Newsom issues executive order to accelerate independent oversight and advance the creation of an AI kill switch",
      "url": "https://www.gov.ca.gov/2026/09/18/governor-newsom-issues-executive-order-to-accelerate-independent-oversight-and-advance-the-creation-of-an-ai-kill-switch/",
      "publisher": "Governor of California",
      "authority": "Official announcement explaining the administration’s framing",
      "raw": {
        "path": "operations/product-stewards/newsstand/candidates/california-ai-oversight-order-20260920/source-refresh-20260926.json",
        "sha256": "fccd4e30c1060a89be357331229429ebd4e972fddcf1bf65593da7020dde1f95",
        "locator": "sources.1"
      },
      "exactPassages": [
        {
          "locator": "L51",
          "excerpt": "The order accelerates California’s new law establishing first-in-the-nation independent oversight of AI companies and safety checks and advances the creation of an “AI kill switch.”"
        },
        {
          "locator": "L53",
          "excerpt": "The executive order convenes a group of world-leading experts to provide, within two months, a guide for California to reinforce and strengthen its AI safety and security laws. Proposals under consideration include requiring independent third parties to write safety plans for frontier AI companies, as well as requiring companies to develop an emergency shutoff, or “kill switch,” for frontier models."
        }
      ],
      "limitations": [
        "This is the Governor’s promotional framing; the signed order controls the legal description."
      ]
    },
    {
      "sourceId": "eff-response-20260918",
      "title": "EFF Statement on California Governor’s Executive Order on AI",
      "url": "https://www.eff.org/deeplinks/2026/09/eff-statement-california-governors-executive-order-ai",
      "publisher": "Electronic Frontier Foundation",
      "authority": "Civil-liberties advocacy response",
      "raw": {
        "path": "operations/product-stewards/newsstand/candidates/california-ai-oversight-order-20260920/source-refresh-20260926.json",
        "sha256": "fccd4e30c1060a89be357331229429ebd4e972fddcf1bf65593da7020dde1f95",
        "locator": "sources.2"
      },
      "exactPassages": [
        {
          "locator": "L104",
          "excerpt": "To that end, EFF supports the focus on expanding the reporting requirements under SB 53 (2025) for loss-of-control incidents, alongside third-party investigations."
        },
        {
          "locator": "L105",
          "excerpt": "As the Government Operations Agency prepares its recommendations for the governor, we urge leaders to also realize that the effectiveness of kill switches in advanced AI systems remains an area of active research."
        },
        {
          "locator": "L106",
          "excerpt": "Moreover, we also caution that government-controlled kill switches run the risk of being used as a form of retaliation against protected speech"
        }
      ],
      "limitations": [
        "EFF is an advocacy organization, not a neutral technical evaluator.",
        "Its response supports parts of the order and cautions against other possible implementations; it does not establish technical effectiveness."
      ]
    },
    {
      "sourceId": "governor-experts-update-20260923",
      "title": "Governor Newsom announces world-leading experts to deliver on his AI executive order, including advancing creation of a “kill switch”",
      "url": "https://www.gov.ca.gov/2026/09/23/governor-newsom-announces-world-leading-experts-to-deliver-on-his-ai-executive-order-including-advancing-creation-of-a-kill-switch/",
      "publisher": "Governor of California",
      "authority": "Official current implementation announcement and administration framing",
      "raw": {
        "path": "operations/product-stewards/newsstand/candidates/california-ai-oversight-order-20260920/source-refresh-20260926.json",
        "sha256": "fccd4e30c1060a89be357331229429ebd4e972fddcf1bf65593da7020dde1f95",
        "locator": "sources.3"
      },
      "exactPassages": [
        {
          "locator": "announcement body",
          "excerpt": "The group of experts at the intersection of technology, policy, and governance will help California advance its AI safety and security governance in light of rapidly advancing AI capabilities."
        },
        {
          "locator": "announcement body",
          "excerpt": "Proposals under consideration include requiring independent third parties to be embedded in frontier AI companies to verify safety frameworks and independently assess safety evaluations, as well as requiring companies to develop an emergency shutoff, or “kill switch,” for frontier models."
        }
      ],
      "limitations": [
        "The page names four advisers and describes current implementation activity, but its shutoff language remains a proposal under consideration.",
        "The signed executive order controls the legal effect; this announcement does not establish an installed universal switch or technical effectiveness."
      ]
    }
  ],
